  1	/**
  2	 * GUI API Route Handlers — Repository Registry Domain
  3	 *
  4	 * All REST handlers for the /api/repos and /api/repos/:repoId endpoints.
  5	 * Follows the domain-split pattern established by `api-knowledge.ts` — each
  6	 * API domain gets its own handler file imported from `server.ts`.
  7	 *
  8	 * Routes provided:
  9	 *   GET    /api/repos              — list all declared repositories
 10	 *   GET    /api/repos/:repoId      — get a single repository entry or 404
 11	 *   POST   /api/repos              — create a new repository entry
 12	 *   PUT    /api/repos/:repoId      — update label, folder_names, and/or vision
 13	 *   DELETE /api/repos/:repoId      — remove the declaration (no project data deleted)
 14	 *
 15	 * Validation rules:
 16	 *   - `id` (create): must match SLUG_REGEX; must be unique across existing entries.
 17	 *   - `folder_names`: each name must be unique across ALL entries in the registry.
 18	 *     Create and update operations that would violate this constraint are rejected
 19	 *     with VALIDATION_ERROR (HTTP 400) and a clear error message.
 20	 *   - `label`: non-empty string (min 1 character).
 21	 *   - `vision`: three-horizon object (short_term, mid_term, long_term) — each field
 22	 *     is a nullable string; null means "not yet authored"; empty strings are rejected.
 23	 *
 24	 * Error shape: { code: string, message: string, details?: unknown }
 25	 *   NOT_FOUND        → 404
 26	 *   VALIDATION_ERROR → 400
 27	 *   (unhandled)      → 500
 28	 *
 29	 * STDIO discipline: this file never writes to process.stdout.
 30	 */
 31	
 32	import { readdir } from 'fs/promises';
 33	import { join } from 'path';
 34	import { z } from 'zod';
 35	import { ApiError } from '../src/gui/errors.js';
 36	import {
 37	  loadRegistry,
 38	  saveRegistry,
 39	} from '../src/storage/repository-registry.js';
 40	import {
 41	  RepositoryEntrySchema,
 42	  StrategicVisionSchema,
 43	  type RepositoryEntry,
 44	} from '../src/schema/repository-registry.js';
 45	import { SLUG_REGEX } from '../src/schema/knowledge.js';
 46	import { LedgerStore } from '../src/storage/ledger-store.js';
 47	
 48	// Re-export ApiError so consumers can catch typed errors without importing
 49	// from a separate path.
 50	export { ApiError };
 51	
 52	// ---------------------------------------------------------------------------
 53	// Private helpers
 54	// ---------------------------------------------------------------------------
 55	
 56	function validationError(message: string, details?: unknown): never {
 57	  throw new ApiError('VALIDATION_ERROR', message, details);
 58	}
 59	
 60	/**
 61	 * Returns the current ISO 8601 timestamp string.
 62	 */
 63	function nowIso(): string {
 64	  return new Date().toISOString();
 65	}
 66	
 67	/**
 68	 * Validates that none of the given `folder_names` appear in any existing
 69	 * registry entry. Optionally skips a specific entry by `excludeId` so that
 70	 * an update operation can keep its own existing folder names without conflict.
 71	 *
 72	 * @throws ApiError VALIDATION_ERROR listing the conflicting folder name(s).
 73	 */
 74	function assertNoFolderNameConflicts(
 75	  allEntries: RepositoryEntry[],
 76	  folderNames: string[],
 77	  excludeId?: string
 78	): void {
 79	  const conflicts: string[] = [];
 80	  for (const name of folderNames) {
 81	    const conflict = allEntries.find(
 82	      (e) => e.id !== excludeId && e.folder_names.includes(name)
 83	    );
 84	    if (conflict) {
 85	      conflicts.push(name);
 86	    }
 87	  }
 88	  if (conflicts.length > 0) {
 89	    validationError(
 90	      `folder_names conflict: the following names are already used by another repository entry: ${conflicts.map((n) => `'${n}'`).join(', ')}.`
 91	    );
 92	  }
 93	}
 94	
 95	// ---------------------------------------------------------------------------
 96	// Zod schemas for request bodies
 97	// ---------------------------------------------------------------------------
