 40	    id: string;
 41	    label: string;
 42	    folder_names: string[];
 43	    vision: { short_term: string | null; mid_term: string | null; long_term: string | null };
 44	  }> = {}
 45	): {
 46	  id: string;
 47	  label: string;
 48	  folder_names: string[];
 49	  vision?: { short_term: string | null; mid_term: string | null; long_term: string | null };
 50	} {
 51	  return {
 52	    id: 'my-repo',
