 73	
 74	  // ─── handleListRepos ────────────────────────────────────────────────────
 75	
 76	  describe('handleListRepos (GET /api/repos)', () => {
 77	    // AC-1: empty registry returns empty array
 78	    it('AC-1: returns empty array when no registry file exists', async () => {
 79	      const result = await handleListRepos(ledgerRoot);
