 82	
 83	    it('AC-1: returns all declared repositories', async () => {
 84	      await handleCreateRepo(ledgerRoot, makeCreateBody({ id: 'repo-a', label: 'Repo A', folder_names: ['folder-a'] }));
 85	      await handleCreateRepo(ledgerRoot, makeCreateBody({ id: 'repo-b', label: 'Repo B', folder_names: ['folder-b'] }));
 86	
 87	      const result = await handleListRepos(ledgerRoot);
 88	      expect(result).toHaveLength(2);
