129	          vision: { short_term: null, mid_term: null, long_term: null },
130	        })
131	      );
132	
133	      const result = await handleListRepos(ledgerRoot);
134	      expect(result[0]!.has_vision).toBe(false);
135	    });
136	
137	    it('has_full_vision is true when all three horizons are non-null', async () => {
138	      await handleCreateRepo(
139	        ledgerRoot,
140	        makeCreateBody({
141	          id: 'repo-fv',
142	          folder_names: ['ffv'],
143	          vision: { short_term: 'Ship fast', mid_term: 'Scale up', long_term: 'Market leader' },
144	        })
145	      );
146	
147	      const result = await handleListRepos(ledgerRoot);
148	      expect(result[0]!.has_full_vision).toBe(true);
149	    });
150	
151	    it('has_full_vision is false when only some horizons are non-null', async () => {
152	      await handleCreateRepo(
153	        ledgerRoot,
154	        makeCreateBody({
155	          id: 'repo-pv',
156	          folder_names: ['fpv'],
157	          vision: { short_term: 'Ship fast', mid_term: null, long_term: null },
158	        })
159	      );
160	
161	      const result = await handleListRepos(ledgerRoot);
162	      expect(result[0]!.has_full_vision).toBe(false);
163	    });
164	  });
165	
166	  // ─── handleGetRepo ───────────────────────────────────────────────────────
167	
168	  describe('handleGetRepo (GET /api/repos/:repoId)', () => {
169	    it('AC-5: returns the full entry for an existing repoId', async () => {
170	      const created = await handleCreateRepo(
